#[proc_macro]
pub fn define_enum(input: TokenStream) -> TokenStream {
    let EnumDef { name, variants } = parse_macro_input!(input as EnumDef);
    let variant_idents: Vec<&Ident> = variants.iter().collect();
    let variant_lower: Vec<Ident> = variants.iter().map(|v| format_ident!("{}", v.to_string().to_lowercase())).collect();

    let expanded = quote! {
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        pub enum #name {
            #(#variant_idents),*
        }

        impl #name {
            pub fn from_name(name: &str) -> Option<Self> {
                match name {
                    #(stringify!(#variant_idents) => Some(Self::#variant_idents),)*
                    _ => None,
                }
            }

            pub fn name(&self) -> &'static str {
                match self {
                    #(Self::#variant_idents => stringify!(#variant_idents),)*
                }
            }
        }
    };

    expanded.into()
}
